class Solution {
public:
    int minMoves(vector<vector<int>>& rooks) {
        int n = rooks.size();
        vector<int> rows(n), cols(n);
        for (int i = 0; i < n; ++i) {
            rows[i] = rooks[i][0];
            cols[i] = rooks[i][1];
        }
        sort(rows.begin(), rows.end());
        sort(cols.begin(), cols.end());
        int ans = 0;
        for (int i = 0; i < n; ++i) {
            ans += abs(rows[i] - i) + abs(cols[i] - i);
        }
        return ans;
    }
};

class Solution {
    public int minMoves(int[][] rooks) {
        int n = rooks.length;
        int[] rows = new int[n];
        int[] cols = new int[n];
        for (int i = 0; i < n; ++i) {
            rows[i] = rooks[i][0];
            cols[i] = rooks[i][1];
        }
        Arrays.sort(rows);
        Arrays.sort(cols);
        int ans = 0;
        for (int i = 0; i < n; ++i) {
            ans += Math.abs(rows[i] - i) + Math.abs(cols[i] - i);
        }
        return ans;
    }
}

var minMoves = function(rooks) {
    const n = rooks.length;
    const rows = rooks.map(r => r[0]).sort((a, b) => a - b);
    const cols = rooks.map(r => r[1]).sort((a, b) => a - b);
    let ans = 0;
    for (let i = 0; i < n; ++i) {
        ans += Math.abs(rows[i] - i) + Math.abs(cols[i] - i);
    }
    return ans;
};
